import { useEffect, useMemo, useState } from 'react';
import { AlertTriangle, ArrowRight, CheckCircle2, Clock3, ExternalLink, FileText, Info, Link2, MessageSquareText, Plus, CalendarClock, History, Pencil, ChevronDown, LoaderCircle, Settings2, Flag, PauseCircle, PlayCircle } from 'lucide-react';
import { Link, useParams, useSearchParams } from 'react-router-dom';
import { memberDirectorySearch, uploadToStaging, workflow, workspaceProject } from '../lib/api';
import { useAuth } from '../hooks/useAuth';
import type { Milestone, MilestoneStatus, ProjectActivityEntry, ProjectBundle } from '../lib/types';
import { formatDate, formatDateTime, milestoneStatusLabel } from '../lib/labels';
import { Modal } from '../components/Modal';

const editableStatuses: MilestoneStatus[]=['IN_PROGRESS','READY_FOR_VERIFICATION','BLOCKED'];
const viewStatus=(status:MilestoneStatus):MilestoneStatus=>status==='NOT_STARTED'?'IN_PROGRESS':status==='AT_RISK'?'BLOCKED':status==='VERIFIED'?'READY_FOR_VERIFICATION':status;
const statusText:Record<string,string>={IN_PROGRESS:'جارٍ العمل',READY_FOR_VERIFICATION:'اكتمل',BLOCKED:'تعثر'};
const updateMeta:Record<string,{label:string,tone:string}>={PROGRESS:{label:'تقدم جديد',tone:'progress'},NO_PROGRESS:{label:'لا يوجد تقدم',tone:'quiet'},BLOCKER:{label:'عائق / تأخر',tone:'blocker'},DEADLINE_CHANGE:{label:'طلب تغيير الموعد',tone:'change'}};
const activityNames:Record<string,string>={MILESTONE_UPDATE:'تحديث محطة',PERIODIC_CHECKIN:'إفادة دورية',SECRETARY_NOTE:'ملاحظة السكرتير',INTERVENTION:'تدخل السكرتير',REFERENCE:'مرجع للعمل',LEAD_NOTE:'ملاحظة المسؤول',SUPERVISOR_ASSIGNMENT:'تكليف المتابع',DESIGN_CHANGE:'تغيير في محطات الإنجاز',PROJECT_CHANGE:'تعديل بيانات المشروع',GS_DECISION:'قرار السكرتير العام'};
const isClosed=(s:string)=>['READY_FOR_VERIFICATION','VERIFIED','CANCELLED'].includes(s);
const isLate=(date?:string|null)=>!!date&&new Date(date).getTime()<Date.now();
const displayRisk=(m:Milestone)=>m.status==='BLOCKED'?'متعثر':m.status==='AT_RISK'?'مهدد':isLate(m.due_at)&&!isClosed(m.status)?'متأخر':null;
const safeHttps=(url:string)=>{try{return new URL(url).protocol==='https:'}catch{return false}};
const initialMilestone={title:'',verificationCriteria:'',dueAt:'',deadlineMode:'ABSOLUTE',relativeDays:7,relativeHours:0,relativeToMilestoneId:''};
const localDateTime=(date?:string|null)=>date?new Date(new Date(date).getTime()-new Date(date).getTimezoneOffset()*60000).toISOString().slice(0,16):'';
const updateTypes=Object.entries(updateMeta).map(([value,meta])=>({value,label:meta.label}));

export default function WorkspaceProjectPage(){
 const {id}=useParams();const {profile}=useAuth();const [searchParams,setSearchParams]=useSearchParams();
 const [bundle,setBundle]=useState<ProjectBundle|null>(null);const [loading,setLoading]=useState(true);
 const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [notice,setNotice]=useState('');
 const [reviewTarget,setReviewTarget]=useState<'progress'|'result'>('progress');const [reviewKind,setReviewKind]=useState('PROGRESS_OK');const [reviewNote,setReviewNote]=useState('');
 const [draftStatus,setDraftStatus]=useState<Record<string,MilestoneStatus>>({});
 const [draftNote,setDraftNote]=useState<Record<string,string>>({});const [draftNext,setDraftNext]=useState<Record<string,string>>({});const [correctionDue,setCorrectionDue]=useState('');
 const [draftOutcome,setDraftOutcome]=useState<Record<string,string>>({});const [draftType,setDraftType]=useState<Record<string,string>>({});
 
 const [reference,setReference]=useState({note:'',referenceUrl:''});
 const [fileDraft,setFileDraft]=useState<Record<string,File|null>>({});const [uploadNotice,setUploadNotice]=useState('');
 const [note,setNote]=useState('');const [intervention,setIntervention]=useState({reason:'',actionText:'',dueAt:''});
 const [modal,setModal]=useState<string|null>(null);const [selected,setSelected]=useState<Milestone|null>(null);
 const [milestoneForm,setMilestoneForm]=useState({...initialMilestone});
 const [gsReason,setGsReason]=useState('');const [requestNote,setRequestNote]=useState('');const [decisionNote,setDecisionNote]=useState('');const [deadlineDraft,setDeadlineDraft]=useState({proposedDueAt:'',reason:''});const [ownerQuery,setOwnerQuery]=useState('');const [ownerResults,setOwnerResults]=useState<{id:string;full_name:string;university_id:string|null;email:string}[]>([]);const [closureType,setClosureType]=useState<'SUCCEEDED'|'CANCELLED'|'POSTPONED'>('SUCCEEDED');const [closureReason,setClosureReason]=useState('');const [closureResume,setClosureResume]=useState('');const [closureDecisionNote,setClosureDecisionNote]=useState('');const [supervisorQuery,setSupervisorQuery]=useState('');const [supervisorResults,setSupervisorResults]=useState<{id:string;full_name:string;university_id:string|null;email:string}[]>([]);
 async function load(){if(!id)return;const b=await workspaceProject(id);setBundle(b);setDraftStatus(Object.fromEntries(b.milestones.map(m=>[m.id,m.status])));setDraftNote({});setDraftOutcome({});}
 useEffect(()=>{let active=true;setLoading(true);setError('');if(id)workspaceProject(id).then(b=>{if(!active)return;setBundle(b);setDraftStatus(Object.fromEntries(b.milestones.map(m=>[m.id,m.status])));setLoading(false)}).catch(e=>{if(active){setError(e?.message||'تعذر تحميل بيانات المشروع');setLoading(false)}});return()=>{active=false}},[id]);
 async function act(action:string,payload:Record<string,unknown>){if(busy)return false;setBusy(true);setError('');setNotice('');try{const response=await workflow(action,payload);try{await load()}catch{setNotice('تم حفظ الإجراء، لكن تعذر تحديث العرض. أعد تحميل المشروع لرؤية البيانات الجديدة.')}setModal(null);setNotice(prev=>prev||response?.warning||'تم تنفيذ الإجراء بنجاح');window.setTimeout(()=>setNotice(''),5000);return true}catch(e:any){setError(e?.message||'تعذر تنفيذ الإجراء');return false}finally{setBusy(false)}}
 const init=bundle?.initiative;const result=bundle?.results[0];
 const lead=!!(profile&&init&&(init.owner_id===profile.id||result?.owner_id===profile.id));
 const secretary=!!(profile&&init&&(profile.role==='ADMIN'||init.secretary_id===profile.id||(profile.role==='SECRETARY'&&profile.secretariat_id===init.secretariat_id)));
 const gs=!!profile&&['GS','ADMIN'].includes(profile.role);const supervisor=secretary||!!(profile&&bundle?.supervisor?.supervisor_id===profile.id);
 const maySupervise=supervisor&&!!profile&&(profile.id!==init?.owner_id||(profile.role==='SECRETARY'&&profile.id===init?.secretary_id));
 const reviewable=init?.approval_status==='APPROVED'&&init.setup_status==='ACTIVE'&&!['COMPLETED','CANCELLED'].includes(init.status)&&init.lifecycle_state!=='POSTPONED';
 const executing=reviewable&&init?.status!=='COMPLETED'&&init?.lifecycle_state!=='POSTPONED';
 // A notification opens the action, not merely the project home page.
 useEffect(()=>{const milestoneId=searchParams.get('milestone');if(!milestoneId||!bundle)return;
  const target=bundle.milestones.find(m=>m.id===milestoneId);
  const action=searchParams.get('action');
  if(target){
   if(action==='review'&&maySupervise&&reviewable)openReview(target,['READY_FOR_VERIFICATION','VERIFIED'].includes(target.status)?'result':'progress');
   else if(action==='update'&&lead&&executing)openUpdate(target);
   else if(action==='deadline'&&maySupervise&&reviewable)openAction('deadline-decide',target);
    else if(action==='request-update'&&maySupervise&&reviewable)openAction('update-request',target);
   else{setSelected(target);setModal('milestone-info');}
  }
  const next=new URLSearchParams(searchParams);next.delete('milestone');next.delete('action');setSearchParams(next,{replace:true});
 },[bundle,searchParams,setSearchParams,lead,maySupervise,reviewable,executing]);

 useEffect(()=>{if(!bundle||searchParams.get('action')!=='closure'||!secretary)return;setModal('closure-decide');const next=new URLSearchParams(searchParams);next.delete('action');setSearchParams(next,{replace:true});},[bundle,secretary,searchParams,setSearchParams]);
 const milestones=useMemo(()=>[...(bundle?.milestones||[])].filter(m=>m.design_status!=='REJECTED').sort((a,b)=>(a.sequence_no||999)-(b.sequence_no||999)||new Date(a.due_at).getTime()-new Date(b.due_at).getTime()),[bundle]);
 const activities=bundle?.activity||[];const overdue=false;
 const total=milestones.length;const verified=milestones.filter(m=>['READY_FOR_VERIFICATION','VERIFIED'].includes(m.status)).length;
 const stalled=milestones.filter(m=>displayRisk(m));
 const effectiveRisk=stalled.some(m=>m.status==='BLOCKED')||!!bundle?.blockers.length?'يوجد تعثر':stalled.length?'محطات تحتاج انتباهًا':'لا توجد إشارات تأخير';
 const latestProjectUpdate=bundle?.activity.find(e=>e.kind==='MILESTONE_UPDATE');
 const pendingClosure=bundle?.closureRequests?.find(q=>q.status==='PENDING');
 const lifecycleLabel=init?.lifecycle_state==='POSTPONED'?'مؤجل':init?.status==='COMPLETED'?'مغلق بنجاح':init?.status==='CANCELLED'?'ملغى':pendingClosure?'طلب إنهاء بانتظار القرار':'قيد التنفيذ';
 const currentStation=[...milestones].filter(m=>!['READY_FOR_VERIFICATION','VERIFIED','CANCELLED'].includes(m.status)).sort((a,b)=>new Date(a.due_at).getTime()-new Date(b.due_at).getTime())[0]||milestones[milestones.length-1];
 const stationLastUpdate=currentStation?activities.find(a=>a.milestone_id===currentStation.id&&a.kind==='MILESTONE_UPDATE'):undefined;
 const stationSchedule=bundle?.followupSchedules.find(s=>s.milestone_id===currentStation?.id);
 const stationReview=stationLastUpdate?bundle?.supervisionEvents.find(e=>e.source_activity_id===stationLastUpdate.id&&['PROGRESS_OK','PROGRESS_FOLLOW_UP','PROGRESS_UNCLEAR','PROGRESS_UNCLEAR','RESULT_OK','RESULT_REVISION'].includes(e.event_type)):undefined;
 const stationCorrection=stationReview?.correction_due_at;
 const projectTimeline=[
  ...activities.map(e=>({key:`activity-${e.id}`,time:e.created_at,milestoneId:e.milestone_id,title:activityNames[e.kind]||e.kind,actor:e.author?.full_name||'عضو الفريق',note:[e.note,typeof e.details?.outcome==='string'?`النتيجة: ${e.details.outcome}`:''].filter(Boolean).join(' — ')})),
  ...(bundle?.supervisionEvents||[]).map(e=>({key:`review-${e.id}`,time:e.created_at,milestoneId:e.milestone_id,title:({PROGRESS_OK:'التقدم مناسب',PROGRESS_FOLLOW_UP:'التقدم غير كافٍ',PROGRESS_UNCLEAR:'الإفادة غير واضحة',RESULT_OK:'النتيجة مناسبة',RESULT_REVISION:'النتيجة تحتاج تعديلًا',UPDATE_REQUEST:'طلب تحديث',REQUEST_ANSWERED:'استجابة لطلب تحديث',PROGRESS_REVIEW:'اطلاع على سير العمل',COMPLETION_READ:'اطلاع على النتيجة'} as Record<string,string>)[e.event_type]||e.event_type,actor:e.actor?.full_name||'المتابع',note:e.note||''})),
  ...(bundle?.deadlineRequests||[]).flatMap(e=>[{key:`deadline-request-${e.id}`,time:e.created_at,milestoneId:e.milestone_id,title:'طلب تغيير الموعد',actor:'مسؤول المشروع',note:`${formatDateTime(e.original_due_at)} ← ${formatDateTime(e.proposed_due_at)} · ${e.reason}`},...(e.decided_at?[{key:`deadline-decision-${e.id}`,time:e.decided_at,milestoneId:e.milestone_id,title:e.status==='APPROVED'?'الموافقة على تعديل الموعد':'رفض تعديل الموعد',actor:'المشرف',note:e.decision_note||''}]:[])]),
  ...(bundle?.evidence||[]).map(e=>({key:`file-${e.id}`,time:e.created_at,milestoneId:e.milestone_id,title:'إضافة دليل للعمل',actor:'مسؤول المشروع',note:e.note||e.evidence_type})),
  ...(bundle?.closureRequests||[]).flatMap(q=>[{key:`closure-request-${q.id}`,time:q.requested_at,milestoneId:null as string|null,title:'طلب مصير المشروع',actor:'المتابع',note:`${q.type==='SUCCEEDED'?'نجاح':q.type==='CANCELLED'?'إلغاء':'تأجيل'} — ${q.reason}`},...(q.decided_at?[{key:`closure-decision-${q.id}`,time:q.decided_at,milestoneId:null as string|null,title:q.status==='APPROVED'?'اعتماد قرار مصير المشروع':'رفض الطلب',actor:'السكرتير',note:q.decision_note||''}]:[])]),
  ...(init?.created_at?[{key:'project-created',time:init.created_at,milestoneId:null as string|null,title:'إنشاء المشروع',actor:init.secretary?.full_name||'السكرتير',note:init.objective||''}]:[]),
  ...(init?.gs_approved_at&&!activities.some(e=>e.kind==='GS_DECISION')?[{key:'project-approved',time:init.gs_approved_at,milestoneId:null as string|null,title:'اعتماد قرار تكليف المشروع',actor:'السكرتير العام',note:''}]:[])
 ].sort((a,b)=>new Date(b.time).getTime()-new Date(a.time).getTime());

 async function saveMilestone(m:Milestone){
  const status=draftStatus[m.id]||m.status;const leadNote=draftNote[m.id]?.trim()||'';const outcome=draftOutcome[m.id]?.trim()||'';const updateType=draftType[m.id]||'PROGRESS';const nextStep=draftNext[m.id]?.trim()||'';
  if(updateType==='DEADLINE_CHANGE'){openAction('deadline',m);return;}
  if(status===m.status&&updateType!=='NO_PROGRESS'&&leadNote===String(m.lead_note||'')&&(!outcome||outcome===String(m.outcome_text||''))&&!nextStep){setError('لم يتغير شيء في هذا التحديث. اكتب ما حدث بالفعل أو اختر «لا يوجد تقدم جديد».');return;}
  if(status!=='READY_FOR_VERIFICATION'&&(!leadNote||!nextStep)){setError('سجل ما حدث فعليًا والخطوة القادمة حتى يستطيع المتابع تقييم التقدم.');return;}
   if(status==='READY_FOR_VERIFICATION'&&!outcome){setError('وصف النتيجة المتحققة ضروري عند إعلان اكتمال المحطة.');return;}
  const ok=await act('MILESTONE_PROGRESS_UPDATE',{milestoneId:m.id,status,leadNote:leadNote||m.lead_note||null,outcomeText:outcome||m.outcome_text||null,updateType,nextStep});
  if(ok)setSelected(null);
 }
 async function sendFile(m:Milestone){
  const file=fileDraft[m.id];if(!file)return;
  setBusy(true);setError('');setUploadNotice('');
  try{
   const stagingPath=await uploadToStaging(file);
   await workflow('EVIDENCE_FILE_ADD',{milestoneId:m.id,stagingPath,fileName:file.name,mimeType:file.type||'application/octet-stream',note:draftNote[m.id]||'',submitForVerification:false});
   setFileDraft(v=>({...v,[m.id]:null}));setUploadNotice(`أُرسل الملف «${file.name}» للأرشفة. يصبح متاحًا بعد نجاح الحفظ في Google Drive.`);
   await load();
  }catch(e:any){setError(e?.message||'تعذر حفظ الملف')}finally{setBusy(false)}
 }
 function openAction(kind:string,m?:Milestone){setSelected(m||null);if(kind==='deadline')setDeadlineDraft({proposedDueAt:localDateTime(m?.due_at),reason:''});setModal(kind);setNote('');setReference({note:'',referenceUrl:''});setIntervention({reason:'',actionText:'',dueAt:''});if(kind==='update-request')setRequestNote('');if(kind==='deadline-decide')setDecisionNote('');}
 function openUpdate(m:Milestone, status?:MilestoneStatus){setSelected(m);setDraftStatus(v=>({...v,[m.id]:status||viewStatus(m.status)}));setDraftType(v=>({...v,[m.id]:status==='BLOCKED'?'BLOCKER':v[m.id]==='DEADLINE_CHANGE'?'PROGRESS':v[m.id]||'PROGRESS'}));setDraftNote(v=>({...v,[m.id]:''}));setDraftNext(v=>({...v,[m.id]:''}));setDraftOutcome(v=>({...v,[m.id]:m.outcome_text||''}));setModal('update');}
 function openReview(m:Milestone,target:'progress'|'result'){setSelected(m);setReviewTarget(target);setReviewKind(target==='result'?'RESULT_OK':'PROGRESS_OK');setReviewNote('');const tomorrow=new Date(Date.now()+24*3600000);setCorrectionDue(localDateTime(tomorrow.toISOString()));setModal('review');}
 function openMilestoneEditor(m?:Milestone){setSelected(m||null);setMilestoneForm(m?{title:m.title,verificationCriteria:m.verification_criteria||'',dueAt:localDateTime(m.due_at),deadlineMode:m.deadline_mode||'ABSOLUTE',relativeDays:m.relative_days||7,relativeHours:m.relative_hours||0,relativeToMilestoneId:m.relative_to_milestone_id||''}:{...initialMilestone,deadlineMode:'ABSOLUTE'});setModal(m?'milestone-edit':'milestone-add')}
 function line(entry:ProjectActivityEntry){return <article className="followup-event" key={entry.id}>
   <div className="followup-event-meta"><strong>{entry.author?.full_name||'عضو الفريق'}</strong><span>{activityNames[entry.kind]||entry.kind} · {formatDateTime(entry.created_at)}</span></div>
   {entry.status_after&&<span className="followup-event-status">الحالة: {milestoneStatusLabel[entry.status_after as MilestoneStatus]||entry.status_after}</span>}
   {entry.note&&<p>{entry.note}</p>}
   {entry.reference_url&&<a href={entry.reference_url} target="_blank" rel="noopener noreferrer"><ExternalLink size={13}/> فتح المرجع المرتبط</a>}
   {typeof entry.details?.outcome==='string'&&<small>المخرج: {entry.details.outcome}</small>}
  </article>}
 if(loading)return <div className="workspace-empty"><Clock3/>جارٍ تحميل لوحة المشروع…</div>;
 if(!init||!bundle)return <div className="workspace-stack"><div className="member-form-error">{error||'لم نعثر على المشروع.'}</div><button className="workspace-secondary" onClick={()=>window.location.reload()}>إعادة المحاولة</button></div>;
 return <div className="workspace-stack workspace-project-v2 followup-page">
   <div className="workspace-back"><Link to="/workspace/projects"><ArrowRight size={16}/>المشاريع</Link></div>
   <header className="followup-hero">
    <div><div className="workspace-kicker">{init.secretariat?.name_ar} · متابعة مشروع</div><h1>{init.title}</h1><p>{result?.statement||init.objective}</p>
     <div className="followup-meta"><span>المسؤول: <b>{init.owner?.full_name||'—'}</b></span><span>الموعد النهائي: <b>{formatDateTime(init.target_due_at)}</b></span><span>آخر تحديث للمحطات: <b>{latestProjectUpdate?formatDateTime(latestProjectUpdate.created_at):'لم تصل إفادة بعد'}</b></span><span className={`v57-lifecycle ${init.lifecycle_state==='POSTPONED'?'status-postponed':init.status==='COMPLETED'?'status-succeeded':init.status==='CANCELLED'?'status-cancelled':'status-active'}`}>{lifecycleLabel}</span></div>
    </div><div className="followup-progress"><div className="v57-project-tools">{(maySupervise||secretary)&&<button className="workspace-secondary small" onClick={()=>setModal('assignment-manage')}><Settings2 size={15}/>إدارة التكليف</button>}{executing&&maySupervise&&!pendingClosure&&<button className="workspace-primary small v57-closure-trigger" onClick={()=>{setClosureReason('');setClosureType('SUCCEEDED');setClosureResume('');setModal('closure-request')}}><Flag size={16}/>إنهاء / إلغاء / تأجيل</button>}{pendingClosure&&secretary&&<button className="workspace-primary small" onClick={()=>setModal('closure-decide')}>قرار المشروع <span className="v57-count-dot">1</span></button>}</div><button type="button" className="workspace-secondary small v53-project-history-btn" onClick={()=>setModal('project-log')}><History size={15}/> سجل المشروع الكامل</button><strong>{verified} / {total}</strong><span>محطات أبلغ المسؤول باكتمالها</span><div className="followup-progress-track"><i style={{width:`${total?Math.round(verified/total*100):0}%`}}/></div></div>
   </header>
   <div className="v56-project-actions">

     {pendingClosure&&<div className="v56-pending-closure"><Clock3 size={16}/> طلب {pendingClosure.type==='SUCCEEDED'?'الإغلاق بنجاح':pendingClosure.type==='CANCELLED'?'الإلغاء':'التأجيل'} بانتظار قرار السكرتير {secretary&&<button className="workspace-primary small" onClick={()=>setModal('closure-decide')}>مراجعة الطلب</button>}</div>}
     {init.lifecycle_state==='POSTPONED'&&secretary&&<button className="workspace-primary small" disabled={busy} onClick={()=>void act('PROJECT_RESUME',{initiativeId:init.id})}><PlayCircle size={16}/>استئناف المشروع</button>}
   </div>
   {currentStation&&<section className="v56-focus-card" aria-label="المحطة الأبرز حاليًا"><div className="v56-focus-head"><div><span className="workspace-kicker">المحطة الأبرز حاليًا</span><h2>{currentStation.title}</h2></div><span className="v54-static-state">{statusText[viewStatus(currentStation.status)]||'جارٍ العمل'}</span></div><p className="v56-focus-update">{stationLastUpdate?.note||(stationLastUpdate?.details?.outcome as string)||'لم يسجّل تحديث على هذه المحطة بعد.'}</p><div className="v64-focus-insight"><div><small>آخر تقييم للمستجد</small><strong>{stationReview?stationReview.event_type==='PROGRESS_OK'?'التقدم مناسب':stationReview.event_type==='PROGRESS_FOLLOW_UP'?'التقدم غير كافٍ':stationReview.event_type==='PROGRESS_UNCLEAR'?'الإفادة غير واضحة':stationReview.event_type==='RESULT_OK'?'النتيجة مناسبة':'النتيجة تحتاج تعديلًا':stationLastUpdate?'لم يُقيّم المستجد بعد':'بانتظار أول إفادة'}</strong>{stationReview?.note&&<p>{stationReview.note}</p>}</div><div><small>الخطوة القادمة / المتابعة</small><strong>{(stationLastUpdate?.details?.next_step as string)|| (stationCorrection?`متابعة التصحيح في ${formatDateTime(stationCorrection)}`:'بانتظار تحديد الخطوة التالية')}</strong>{stationSchedule&&!isClosed(currentStation.status)&&<p>الإفادة القادمة: {formatDateTime(stationSchedule.next_due_at)}{new Date(stationSchedule.next_due_at).getTime()<Date.now()?' · متأخرة':''}</p>}</div></div><div className="v56-focus-footer"><small>الموعد: {formatDateTime(currentStation.due_at)}</small><small>{stationLastUpdate?`آخر تحديث: ${formatDateTime(stationLastUpdate.created_at)}`:'بانتظار أول تحديث'}</small>{lead&&executing&&<button className="workspace-primary small" onClick={()=>openUpdate(currentStation)}><Pencil size={14}/>تحديث المحطة</button>}{maySupervise&&reviewable&&stationLastUpdate&&!stationReview&&<button className="workspace-secondary small" onClick={()=>openReview(currentStation,['READY_FOR_VERIFICATION','VERIFIED'].includes(currentStation.status)?'result':'progress')}>{['READY_FOR_VERIFICATION','VERIFIED'].includes(currentStation.status)?'تقييم النتيجة':'تقييم المستجد'}</button>}</div></section>}
   <section className="workspace-card v64-stations" aria-label="محطات المشروع">
    <div className="v64-stations-head"><div><h2>محطات الإنجاز</h2><p>افتح المستجدات والتقييمات في محطتها دون ازدحام.</p></div><span>{verified} / {total} أُبلغ باكتمالها</span></div>
    {milestones.map((m,index)=>{const last=activities.find(a=>a.milestone_id===m.id&&a.kind==='MILESTONE_UPDATE');const sch=bundle.followupSchedules.find(x=>x.milestone_id===m.id);const lastReview=last?bundle.supervisionEvents.find(e=>e.source_activity_id===last.id&&['PROGRESS_OK','PROGRESS_FOLLOW_UP','PROGRESS_UNCLEAR','PROGRESS_UNCLEAR','RESULT_OK','RESULT_REVISION'].includes(e.event_type)):undefined;const completed=isClosed(m.status);return <div className="v64-station-row" key={m.id}>
     <div className="v64-station-number">{index+1}</div><div className="v64-station-content"><strong>{m.title}</strong><small>الموعد: {formatDateTime(m.due_at)}{sch&&!completed?` · الإفادة القادمة: ${formatDateTime(sch.next_due_at)}`:''}</small><p>{last?.note||(last?.details?.outcome as string)||(completed?'أُبلغ باكتمال المحطة':'لم تصل إفادة مسجلة بعد')}</p></div>
     <div className="v64-station-quick"><span className={`v64-status ${displayRisk(m)?'warn':completed?'good':'neutral'}`}>{displayRisk(m)|| (completed?'مكتملة للإجراء':'جارية')}</span>{lastReview&&<small>{lastReview.event_type==='PROGRESS_OK'?'تقدم مناسب':lastReview.event_type==='RESULT_OK'?'نتيجة مناسبة':lastReview.event_type==='PROGRESS_FOLLOW_UP'?'تقدم غير كافٍ':lastReview.event_type==='PROGRESS_UNCLEAR'?'إفادة غير واضحة':'النتيجة تحتاج تعديلًا'}</small>}</div>
     <div className="v64-station-tools">{lead&&executing&&!completed&&<button className="workspace-primary small" onClick={()=>openUpdate(m)}>تحديث</button>}{maySupervise&&reviewable&&last&&!lastReview&&<button className="workspace-secondary small" onClick={()=>openReview(m,completed?'result':'progress')}>تقييم</button>}<button className="workspace-secondary small" onClick={()=>{setSelected(m);setModal('milestone-log')}}>السجل</button></div>
    </div>})}
   </section>
   {busy&&<div className="v54-saving-overlay" role="status"><LoaderCircle size={18} className="v54-spin"/>جارٍ تنفيذ طلبك…</div>}{error&&<div className="member-form-error" role="alert">{error}</div>}{notice&&<div className="v54-toast" role="status"><CheckCircle2 size={17}/>{notice}</div>}{uploadNotice&&<div className="workspace-review-banner" role="status">{uploadNotice}</div>}
   {init.approval_status!=='APPROVED'&&<section className="workspace-review-banner"><Clock3/><div><strong>{init.approval_status==='PENDING_GS'?'بانتظار اعتماد GS':'المشروع لم يدخل مرحلة التنفيذ'}</strong><span>لا يوجد تحديث أو تدخل تنفيذي قبل اعتماد التكليف. يمكن مراجعة الخطة فقط.</span></div>{init.approval_status==='PENDING_GS'&&gs&&<div className="workspace-inline-actions"><button className="workspace-secondary" onClick={()=>setModal('gs-return')}>إعادة للمراجعة</button><button className="workspace-primary" disabled={busy} onClick={()=>act('PROJECT_GS_DECIDE',{initiativeId:init.id,decision:'APPROVE'})}>اعتماد التكليف</button></div>}{init.approval_status==='RETURNED'&&secretary&&<button className="workspace-primary" disabled={busy} onClick={()=>act('PROJECT_RESUBMIT_GS',{initiativeId:init.id})}>إعادة للإجازة</button>}</section>}
   <details className="workspace-card followup-table-card v54-sheet-shell v64-milestone-details"><summary>عرض جميع محطات الإنجاز وتفاصيل تقييمها <ChevronDown size={16}/></summary>
    <div className="workspace-card-head v54-sheet-head"><div><h2>محطات الإنجاز</h2><p>كل شيء في جدول واحد · اضغط الحالة لتحديثها · ⓘ لتاريخ وسجل المحطة</p></div>{secretary&&<button className="workspace-secondary small" onClick={()=>openMilestoneEditor()}><Plus size={15}/>محطة جديدة</button>}</div>
    <div className="v54-scroll-guide">يمكن تمرير الجدول أفقيًا على الشاشات الصغيرة؛ لا تحتاج للنزول إلى أسفل الصفحة من أجل تعديل محطة.</div>
    <div className="followup-scroll v54-scroll"><table className="followup-table v54-sheet"><thead><tr><th>المحطة</th><th>الموعد</th><th>الحالة</th><th>آخر ما حدث</th><th>النتيجة</th><th>تقييم التحديث</th><th>تقييم النتيجة</th><th>ملاحظات المشرف</th></tr></thead>
    <tbody>{milestones.map((m,index)=>{
     const events=activities.filter(e=>e.milestone_id===m.id&&e.kind==='MILESTONE_UPDATE');
     const lastUpdate=events[0];
     const newestDeadline=bundle.deadlineRequests.find(e=>e.milestone_id===m.id);
     const deadlineIsLatest=!!newestDeadline&&(!lastUpdate||new Date(newestDeadline.created_at).getTime()>new Date(lastUpdate.created_at).getTime());
     const lastShownTime=deadlineIsLatest?newestDeadline?.created_at:lastUpdate?.created_at;
     const lastShownText=deadlineIsLatest?`طلب تغيير الموعد إلى ${formatDateTime(newestDeadline!.proposed_due_at)}: ${newestDeadline!.reason}`:lastUpdate?.note;
     // The current review belongs ONLY to the latest submitted progress update.
     // Earlier reviews stay in the immutable timeline but cannot endorse a new update.
     const completed=['READY_FOR_VERIFICATION','VERIFIED'].includes(m.status);
     const lastProgress=events.find(e=>!['READY_FOR_VERIFICATION','VERIFIED'].includes(e.status_after||'')&&String(e.details?.update_type||'')!=='DEADLINE_CHANGE')||null;
     const progressReview=bundle.supervisionEvents.find(e=>e.milestone_id===m.id&&['PROGRESS_OK','PROGRESS_FOLLOW_UP','PROGRESS_UNCLEAR'].includes(e.event_type)&&e.source_activity_id===lastProgress?.id);
     const resultUpdate=events.find(e=>e.status_after==='READY_FOR_VERIFICATION');
     const resultReview=bundle.supervisionEvents.find(e=>e.milestone_id===m.id&&['RESULT_OK','RESULT_REVISION'].includes(e.event_type)&&e.source_activity_id===resultUpdate?.id);
     const revisions=resultReview?.event_type==='RESULT_REVISION';
     const latestFeedback=bundle.supervisionEvents.find(e=>e.milestone_id===m.id&&e.source_activity_id===(completed?resultUpdate?.id:lastProgress?.id)&&['PROGRESS_FOLLOW_UP','PROGRESS_UNCLEAR','RESULT_REVISION'].includes(e.event_type));
     const leadCanEdit=lead&&(executing||(revisions&&init.approval_status==='APPROVED'))&&m.status!=='VERIFIED'&&m.status!=='CANCELLED';
     const pendingDeadline=bundle.deadlineRequests.find(e=>e.milestone_id===m.id&&e.status==='PENDING');
     const lastUpdateRequest=bundle.supervisionEvents.find(e=>e.milestone_id===m.id&&e.event_type==='UPDATE_REQUEST');
     const updateRequestPending=!!lastUpdateRequest&&!bundle.supervisionEvents.some(e=>e.event_type==='REQUEST_ANSWERED'&&e.related_request_id===lastUpdateRequest.id);
     const kind=deadlineIsLatest?'DEADLINE_CHANGE':String(lastUpdate?.details?.update_type||'');
     return <tr key={m.id} className={displayRisk(m)?'v54-danger-row':''}>
      <td><div className="v54-m-title"><span className="v54-index">{index+1}</span><div><strong>{m.title}</strong><small title={m.verification_criteria}>{m.verification_criteria||' '}</small></div></div></td>
      <td><div className="v54-deadline"><span>{formatDateTime(m.due_at)}</span>{leadCanEdit&&!completed&&<button className="v54-icon-btn" title="طلب تغيير الموعد" onClick={()=>openAction('deadline',m)}><CalendarClock size={16}/></button>}</div>{pendingDeadline&&<small className="v54-pending">موعد جديد بانتظار القرار</small>}{pendingDeadline&&maySupervise&&<button className="v54-inline-edit" onClick={()=>openAction('deadline-decide',m)}>مراجعة طلب الموعد</button>}{isLate(m.due_at)&&!completed&&<small className="v54-overdue">تجاوز الموعد</small>}</td>
      <td>{leadCanEdit&&!completed?<div className={`v54-state-select v54-state-${viewStatus(m.status).toLowerCase()}`}><select aria-label={`حالة ${m.title}`} value={viewStatus(m.status)} disabled={busy} onChange={e=>openUpdate(m,e.target.value as MilestoneStatus)}>{editableStatuses.map(st=><option key={st} value={st}>{statusText[st]}</option>)}</select><ChevronDown size={15}/></div>:<span className={`v54-static-state v54-state-${viewStatus(m.status).toLowerCase()}`}>{statusText[viewStatus(m.status)]||'جارٍ العمل'}</span>}</td>
      <td><div className="v54-last"><div className="v54-last-top">{lastShownTime&&<span className={`v54-kind v54-kind-${updateMeta[kind]?.tone||'quiet'}`}>{updateMeta[kind]?.label||'تحديث'}</span>}{lastShownTime?<button title={`آخر تحديث: ${formatDateTime(lastShownTime)}`} aria-label={`معلومات آخر تحديث للمحطة ${m.title}`} className="v54-icon-btn" onClick={()=>{setSelected(m);setModal('milestone-info')}}><Info size={16}/></button>:null}</div><span className="v54-truncate" title={lastShownText||''}>{lastShownText||'لم يسجل تحديث بعد'}</span>{leadCanEdit&&<button className="v54-inline-edit" onClick={()=>openUpdate(m)}><Pencil size={13}/>تحديث</button>}</div></td>
      <td><div className="v54-result"><span className="v54-truncate" title={m.outcome_text||''}>{completed?(m.outcome_text||'لم توصف النتيجة'):'—'}</span>{revisions&&<small className="v54-pending">المشرف طلب تعديل النتيجة</small>}{revisions&&leadCanEdit&&<button className="v54-inline-edit" onClick={()=>openUpdate(m,'READY_FOR_VERIFICATION')}><Pencil size={13}/>تعديل النتيجة</button>}</div></td>
      <td><div className="v54-evaluation"><span className={`v54-eval ${progressReview?.event_type==='PROGRESS_OK'?'good':progressReview?'warn':''}`}>{progressReview?.event_type==='PROGRESS_OK'?'مناسب':progressReview?.event_type==='PROGRESS_FOLLOW_UP'?'غير كافٍ':progressReview?.event_type==='PROGRESS_UNCLEAR'?'غير واضح':lastProgress?'تحديث جديد · لم يُقيّم':'—'}</span>{maySupervise&&reviewable&&!completed&&lastProgress&&!progressReview&&<button className="v54-inline-edit" onClick={()=>openReview(m,'progress')}>تقييم التحديث</button>}</div></td>
      <td><div className="v54-evaluation">{completed?<><span className={`v54-eval ${resultReview?.event_type==='RESULT_OK'?'good':resultReview?'warn':''}`}>{resultReview?.event_type==='RESULT_OK'?'النتيجة مناسبة':resultReview?.event_type==='RESULT_REVISION'?'تحتاج تعديلًا':'لم تُقيّم بعد'}</span>{maySupervise&&reviewable&&!resultReview&&<button className="v54-inline-edit" onClick={()=>openReview(m,'result')}>تقييم النتيجة</button>}</>:<span className="v54-empty">—</span>}</div></td>
      <td><div className="v54-notes"><span className="v54-truncate" title={latestFeedback?.note||m.secretary_note||''}>{latestFeedback?.note||m.secretary_note||'—'}</span>{latestFeedback?.note&&<small className="v54-note-author">ملاحظة على {latestFeedback.event_type==='RESULT_REVISION'?'النتيجة':'التقدم'}</small>}{supervisor&&executing&&<button className="v54-inline-edit" onClick={()=>openAction('note',m)}><Pencil size={13}/>إضافة ملاحظة</button>}{maySupervise&&executing&&!completed&&(updateRequestPending?<small className="v54-pending" title="سبق إرسال طلب لهذه المحطة، وينتظر تحديث المسؤول">بانتظار رد المسؤول على طلب التحديث</small>:<button disabled={busy} className="v54-inline-edit" title="يُرسل إشعارًا للمسؤول ليحدّث وضع المحطة" onClick={()=>openAction('update-request',m)}><MessageSquareText size={13}/>طلب تحديث</button>)}</div></td>
     </tr>;
    })}</tbody></table></div>
   </details>
   {executing&&secretary&&<div className="v53-secondary-action"><button className="workspace-secondary small" onClick={()=>openAction('note')}><MessageSquareText size={15}/>إضافة ملاحظة عامة</button></div>}
   <Modal open={modal==='update'} title={`تحديث محطة — ${selected?.title||''}`} onClose={()=>setModal(null)} footer={<button className="workspace-primary" disabled={busy||!selected||((draftStatus[selected?.id||'']||selected.status)==='READY_FOR_VERIFICATION'&&!draftOutcome[selected?.id||'']?.trim())} onClick={()=>selected&&saveMilestone(selected)}>{busy?<><LoaderCircle size={16} className="v54-spin"/>جارٍ الحفظ…</>:'حفظ التحديث'}</button>}>
     {selected&&<div className="v54-form"><div className="v54-two"><div className="field"><label>حالة المحطة</label><select className="select" value={viewStatus(draftStatus[selected.id]||selected.status)} onChange={e=>setDraftStatus(v=>({...v,[selected.id]:e.target.value as MilestoneStatus}))}>{editableStatuses.map(st=><option key={st} value={st}>{statusText[st]}</option>)}</select></div><div className="field"><label>نوع آخر ما حدث</label><select className="select" value={draftType[selected.id]||'PROGRESS'} onChange={e=>{const kind=e.target.value;if(kind==='DEADLINE_CHANGE'){openAction('deadline',selected);return;}setDraftType(v=>({...v,[selected.id]:kind}));if(kind==='BLOCKER')setDraftStatus(v=>({...v,[selected.id]:'BLOCKED'}));}}>{updateTypes.map(t=><option key={t.value} value={t.value}>{t.label}</option>)}</select></div></div><div className="field"><label>ما الذي حدث؟</label><textarea className="textarea" rows={3} value={draftNote[selected.id]||''} placeholder="مثال: استلمنا 12 مقالة بعد مراجعتها" onChange={e=>setDraftNote(v=>({...v,[selected.id]:e.target.value}))}/></div>{viewStatus(draftStatus[selected.id]||selected.status)!=='READY_FOR_VERIFICATION'&&<div className="field"><label>ما الخطوة القادمة؟ *</label><input className="input" value={draftNext[selected.id]||''} placeholder="مثلًا: إرسال المسودة للمتابع صباح الغد" onChange={e=>setDraftNext(v=>({...v,[selected.id]:e.target.value}))}/></div>}{viewStatus(draftStatus[selected.id]||selected.status)==='READY_FOR_VERIFICATION'&&<div className="field"><label>صف النتيجة النهائية بصورة محددة *</label><textarea className="textarea" rows={3} value={draftOutcome[selected.id]||''} placeholder="مثال: اتُفق مع المستشفى على التدريب يوم 13 نوفمبر من 9 حتى 12" onChange={e=>setDraftOutcome(v=>({...v,[selected.id]:e.target.value}))}/></div>}<div className="v54-optional"><button className="workspace-secondary small" onClick={()=>openAction('reference',selected)}><Link2 size={15}/>إضافة رابط / مستند</button><label className="followup-upload-select"><FileText size={15}/>{fileDraft[selected.id]?.name||'اختيار ملف'}<input type="file" accept=".pdf,.png,.jpg,.jpeg,.docx" onChange={e=>setFileDraft(v=>({...v,[selected.id]:e.target.files?.[0]||null}))}/></label>{fileDraft[selected.id]&&<button className="workspace-secondary small" disabled={busy} onClick={()=>sendFile(selected)}>رفع الملف</button>}</div></div>}
   </Modal>
   <Modal open={modal==='review'} title={`${reviewTarget==='result'?'تقييم النتيجة':'تقييم التحديث'} — ${selected?.title||''}`}  onClose={()=>setModal(null)} footer={<button className="workspace-primary" disabled={busy||!selected||(['RESULT_REVISION','PROGRESS_FOLLOW_UP','PROGRESS_UNCLEAR'].includes(reviewKind)&&(!reviewNote.trim()||!correctionDue||!Number.isFinite(new Date(correctionDue).getTime())||new Date(correctionDue).getTime()<=Date.now()))} onClick={()=>selected&&act('MILESTONE_QUALITY_REVIEW',{milestoneId:selected.id,reviewKind,note:reviewNote,correctionDueAt:['PROGRESS_FOLLOW_UP','PROGRESS_UNCLEAR','RESULT_REVISION'].includes(reviewKind)?new Date(correctionDue).toISOString():null,expectedSourceActivityId:activities.find(e=>e.milestone_id===selected.id&&e.kind==='MILESTONE_UPDATE')?.id})}>{busy?'جارٍ الحفظ…':'حفظ التقييم'}</button>}>
     {selected&&<div className="v53-review-dialog"><p className="muted">تقييمك مستقل ولا يوقف استمرار العمل. ستظهر ملاحظتك لمسؤول المشروع مع نوع التقييم.</p><div className="v53-review-snapshot"><strong>المطلوب: {selected.verification_criteria}</strong><span>{reviewTarget==='result'?'النتيجة المسجلة: ':'آخر تحديث: '}{reviewTarget==='result'?selected.outcome_text||'لا توجد نتيجة':activities.find(e=>e.milestone_id===selected.id&&e.kind==='MILESTONE_UPDATE')?.note||'لا يوجد تحديث'}</span></div><div className="v53-review-choices">{(reviewTarget==='result'?[{value:'RESULT_OK',label:'النتيجة مناسبة'},{value:'RESULT_REVISION',label:'تحتاج تعديلًا'}]:[{value:'PROGRESS_OK',label:'مناسب'},{value:'PROGRESS_FOLLOW_UP',label:'التقدم غير كافٍ'},{value:'PROGRESS_UNCLEAR',label:'المستجد غير واضح'}]).map(option=><label key={option.value} className={reviewKind===option.value?'active':''}><input type="radio" name="v53-review" value={option.value} checked={reviewKind===option.value} onChange={()=>setReviewKind(option.value)}/>{option.label}</label>)}</div>{['RESULT_REVISION','PROGRESS_FOLLOW_UP','PROGRESS_UNCLEAR'].includes(reviewKind)&&<div className="field"><label>ما المطلوب من المسؤول؟ *</label><textarea rows={3} className="textarea" value={reviewNote} onChange={e=>setReviewNote(e.target.value)} placeholder="اكتب الملاحظة أو التصحيح المطلوب بوضوح"/><label>موعد التحقق من تنفيذ التصحيح *</label><input type="datetime-local" className="input" value={correctionDue} onChange={e=>setCorrectionDue(e.target.value)}/></div>}</div>}
   </Modal>
   <Modal open={modal==='milestone-info'} title={`آخر تحديث — ${selected?.title||''}`} onClose={()=>setModal(null)} className="v54-quick-info-modal">
    {selected&&<div className="v54-quick-info"><span>تاريخ آخر تحديث</span><strong>{formatDateTime([activities.find(e=>e.milestone_id===selected.id&&e.kind==='MILESTONE_UPDATE')?.created_at,bundle.deadlineRequests.find(e=>e.milestone_id===selected.id)?.created_at].filter(Boolean).sort((a,b)=>new Date(b!).getTime()-new Date(a!).getTime())[0]||selected.status_updated_at)}</strong><small>{activities.find(e=>e.milestone_id===selected.id&&e.kind==='MILESTONE_UPDATE')?.author?.full_name||'مسؤول المشروع'}</small><button className="workspace-secondary" onClick={()=>setModal('milestone-log')}><History size={16}/> عرض سجل المحطة كاملاً</button></div>}
   </Modal>
   <Modal open={modal==='milestone-log'} title={`سجل المحطة — ${selected?.title||''}`} onClose={()=>setModal(null)} className="v53-log-modal">
    {selected&&<div className="v53-timeline">{projectTimeline.filter(e=>e.milestoneId===selected.id).length?projectTimeline.filter(e=>e.milestoneId===selected.id).map(e=><article className="v53-log-event" key={e.key}><small>{formatDateTime(e.time)} · {e.actor}</small><strong>{e.title}</strong>{e.note&&<p>{e.note}</p>}</article>):<p className="muted">لم يسجل أي حدث لهذه المحطة بعد.</p>}</div>}
   </Modal>
   <Modal open={modal==='project-log'} title={`سجل المشروع الكامل — ${init.title}`} onClose={()=>setModal(null)} className="v53-log-modal">
    <p className="muted">سجل زمني للمشروع ومحطاته، بما فيها التحديثات والمراجعات والتفويض وتغييرات المواعيد والأدلة المسجلة.</p><div className="v53-timeline">{projectTimeline.map(e=><article className="v53-log-event" key={e.key}><small>{formatDateTime(e.time)} · {e.actor}{e.milestoneId&&' · '+(milestones.find(m=>m.id===e.milestoneId)?.title||'محطة')}</small><strong>{e.title}</strong>{e.note&&<p>{e.note}</p>}</article>)}</div>
   </Modal>
   <Modal open={modal==='assignment-manage'} title="إدارة تكليف المشروع" onClose={()=>setModal(null)}><div className="v56-manage"><div className="v56-manage-section"><strong>مسؤول التنفيذ الحالي: {init.owner?.full_name||'—'}</strong><p className="muted">يمكن للمتابع المباشر أو السكرتير نقل التنفيذ إلى عضو آخر. يحتفظ المشروع بتاريخه، وتُنقل الصلاحيات التنفيذية مع المسؤول الجديد.</p>{(maySupervise||secretary)&&<><label>ابحث عن المسؤول الجديد</label><input className="input" placeholder="الاسم أو الرقم الجامعي" value={ownerQuery} onChange={e=>{setOwnerQuery(e.target.value);if(e.target.value.trim().length>=2)memberDirectorySearch(e.target.value).then(setOwnerResults).catch(()=>setOwnerResults([]));else setOwnerResults([])}}/><div className="workspace-member-results">{ownerResults.map(x=><button key={x.id} disabled={busy||x.id===init.owner_id} onClick={()=>act('PROJECT_OWNER_REASSIGN',{initiativeId:init.id,ownerId:x.id})}>{busy?'جارٍ نقل المسؤولية…':`تكليف ${x.full_name} · ${x.university_id||''}`}</button>)}</div></>}</div><div className="v56-manage-section"><strong>المتابع المباشر: {bundle.supervisor?.supervisor?.full_name||init.secretary?.full_name||'السكرتير'}</strong><p className="muted">تغيير المشرف أو تفويض النائب من اختصاص السكرتير فقط، وليس مسؤول التنفيذ أو النائب المفوّض.</p>{secretary&&<button className="workspace-secondary" onClick={()=>{setSupervisorQuery('');setSupervisorResults([]);setModal('assign-supervisor')}}><Settings2 size={16}/>تغيير المتابع المباشر</button>}</div></div></Modal>
   <Modal open={modal==='closure-request'} title="طلب إغلاق أو تأجيل المشروع" onClose={()=>setModal(null)} footer={<button className="workspace-primary" disabled={busy||closureReason.trim().length<12||(closureType==='POSTPONED'&&!closureResume)} onClick={()=>void act('PROJECT_CLOSE_REQUEST',{initiativeId:init.id,type:closureType,reason:closureReason,postponeUntilDate:closureResume||null})}>{busy?'جارٍ حفظ القرار…':secretary?'اعتماد القرار الآن':'إرسال الطلب للسكرتير'}</button>}><div className="v56-closure-form"><p className="muted">قرار المشروع منفصل عن إعلان اكتمال المحطات. لا يحذف الإلغاء سجل العمل، ولا يمنع انتظار موافقة السكرتير استكمال العمل.</p><div className="field"><label>نوع القرار</label><select className="select" value={closureType} onChange={e=>setClosureType(e.target.value as typeof closureType)}><option value="SUCCEEDED">إغلاق بنجاح</option><option value="CANCELLED">إلغاء المشروع</option><option value="POSTPONED">تأجيل المشروع</option></select></div><div className="field"><label>{closureType==='SUCCEEDED'?'ما النتيجة النهائية المحققة؟':'سبب القرار وما الذي سيحدث بعده؟'} *</label><textarea className="textarea" rows={4} value={closureReason} onChange={e=>setClosureReason(e.target.value)} placeholder="اكتب سببًا واضحًا وقابلًا للمراجعة"/></div>{closureType==='POSTPONED'&&<div className="field"><label>تأجيل المشروع حتى تاريخ *</label><input className="input" type="date" value={closureResume} onChange={e=>setClosureResume(e.target.value)}/></div>}{busy&&<p className="v57-modal-feedback" role="status">جارٍ إرسال القرار وتحديث السجل…</p>}{error&&<p className="member-form-error" role="alert">{error}</p>}</div></Modal>
   <Modal open={modal==='closure-decide'} title="قرار السكرتير بشأن مصير المشروع" onClose={()=>setModal(null)} footer={<div className="v54-decision-actions"><button className="workspace-secondary" disabled={busy||!pendingClosure||!closureDecisionNote.trim()} onClick={()=>pendingClosure&&void act('PROJECT_CLOSE_DECIDE',{requestId:pendingClosure.id,decision:'REJECT',note:closureDecisionNote})}>رفض مع السبب</button><button className="workspace-primary" disabled={busy||!pendingClosure} onClick={()=>pendingClosure&&void act('PROJECT_CLOSE_DECIDE',{requestId:pendingClosure.id,decision:'APPROVE',note:closureDecisionNote})}>اعتماد القرار</button></div>}>{pendingClosure?<div className="v56-closure-form">{busy&&<p className="v57-modal-feedback" role="status">جارٍ حفظ قرار السكرتير…</p>}{error&&<p className="member-form-error" role="alert">{error}</p>}<p><strong>نوع القرار: </strong>{pendingClosure.type==='SUCCEEDED'?'إغلاق بنجاح':pendingClosure.type==='CANCELLED'?'إلغاء':'تأجيل'}</p><p><strong>السبب / النتيجة: </strong>{pendingClosure.reason}</p>{pendingClosure.resume_review_at&&<p>التأجيل حتى تاريخ: {pendingClosure.postpone_until_date||formatDate(pendingClosure.resume_review_at)}</p>}<div className="field"><label>ملاحظة القرار (إلزامية عند الرفض)</label><textarea className="textarea" value={closureDecisionNote} onChange={e=>setClosureDecisionNote(e.target.value)} rows={3}/></div></div>:<p>لا يوجد طلب معلّق.</p>}</Modal>
   <Modal open={modal==='assign-supervisor'} title="تكليف متابع مباشر (النائب أو غيره)" onClose={()=>setModal(null)}><p className="muted">إذا لم تعيّن شخصًا فالمتابعة المباشرة لدى السكرتير. لا تنتقل سلطة السكرتير العامة إلى الشخص المفوّض.</p><div className="field"><label>ابحث عن عضو بالاسم أو الرقم الجامعي</label><input className="input" value={supervisorQuery} onChange={e=>{setSupervisorQuery(e.target.value);if(e.target.value.trim().length>=2)memberDirectorySearch(e.target.value).then(setSupervisorResults).catch(()=>setSupervisorResults([]));else setSupervisorResults([])}}/></div><div className="workspace-member-results">{supervisorResults.map(x=><button key={x.id} disabled={busy} onClick={()=>act('PROJECT_SUPERVISOR_ASSIGN',{initiativeId:init.id,supervisorId:x.id})}>{x.full_name} · {x.university_id||''}</button>)}</div>{bundle.supervisor&&<button className="workspace-secondary" disabled={busy} onClick={()=>act('PROJECT_SUPERVISOR_ASSIGN',{initiativeId:init.id,supervisorId:null})}>إلغاء التفويض والعودة للسكرتير</button>}</Modal>
   <Modal open={modal==='reference'} title={`إضافة مرجع ${selected?'— '+selected.title:''}`} onClose={()=>setModal(null)} footer={<button className="workspace-primary" disabled={busy||(!reference.note.trim()&&!reference.referenceUrl.trim())||!!reference.referenceUrl&&!safeHttps(reference.referenceUrl)} onClick={()=>act('PROJECT_REFERENCE_ADD',{initiativeId:init.id,milestoneId:selected?.id||null,...reference})}>حفظ المرجع</button>}><div className="field"><label>ماذا يثبت أو يوضح هذا المرجع؟</label><textarea className="textarea" rows={2} value={reference.note} onChange={e=>setReference(v=>({...v,note:e.target.value}))}/></div><div className="field section-gap"><label>رابط رسالة تيليجرام أو مستند (https)</label><input className="input" value={reference.referenceUrl} onChange={e=>setReference(v=>({...v,referenceUrl:e.target.value}))} placeholder="https://t.me/..."/>{reference.referenceUrl&&!safeHttps(reference.referenceUrl)&&<small className="danger-text">أدخل رابط https صحيحًا</small>}</div><p className="muted">الرابط يوثق السياق ولا يُعتبر تحققًا نهائيًا تلقائيًا. روابط المجموعات الخاصة قد لا تكون متاحة للسكرتير العام.</p></Modal>
   <Modal open={modal==='note'} title="ملاحظة المتابع — لا تعني بالضرورة وجود تعثر" onClose={()=>setModal(null)} footer={<button className="workspace-primary" disabled={busy||!note.trim()} onClick={()=>selected?act('MILESTONE_SECRETARY_NOTE',{milestoneId:selected.id,note}):act('PROJECT_SECRETARY_NOTE_ADD',{initiativeId:init.id,milestoneId:null,note})}>{busy?'جارٍ الحفظ…':'حفظ الملاحظة'}</button>}><textarea className="textarea" rows={4} value={note} onChange={e=>setNote(e.target.value)} placeholder="توجيه، سؤال، توصية أو متابعة عادية..."/></Modal>
   <Modal open={modal==='intervention'} title="تدخل السكرتير" onClose={()=>setModal(null)} footer={<button className="workspace-primary" disabled={busy||!intervention.actionText.trim()} onClick={()=>act('PROJECT_INTERVENTION_ADD',{initiativeId:init.id,resultId:result?.id||null,milestoneId:selected?.id||null,...intervention})}>تسجيل التدخل</button>}><div className="field"><label>ما الذي استدعى التدخل؟</label><textarea className="textarea" value={intervention.reason} onChange={e=>setIntervention(v=>({...v,reason:e.target.value}))}/></div><div className="field section-gap"><label>الإجراء الفعلي</label><textarea className="textarea" value={intervention.actionText} onChange={e=>setIntervention(v=>({...v,actionText:e.target.value}))}/></div><div className="field section-gap"><label>متابعة لاحقة (اختياري)</label><input className="input" type="date" value={intervention.dueAt} onChange={e=>setIntervention(v=>({...v,dueAt:e.target.value}))}/></div></Modal>
   <Modal open={modal==='update-request'} title={`طلب تحديث من المسؤول — ${selected?.title||''}`} onClose={()=>setModal(null)} footer={<button className="workspace-primary" disabled={busy||!selected} onClick={()=>selected&&act('MILESTONE_UPDATE_REQUEST',{milestoneId:selected.id,note:requestNote})}>{busy?'جارٍ الإرسال…':'إرسال طلب التحديث'}</button>}>
    <p className="muted">سيرسل النظام إشعارًا لمسؤول المشروع لتوضيح وضع هذه المحطة. لا يمنع الطلب استمرار التنفيذ، ويمكن للمسؤول تسجيل «لا يوجد تقدم» إذا لم يتحقق شيء جديد.</p><div className="field"><label>توضيح السؤال للمسؤول (اختياري)</label><textarea className="textarea" rows={2} value={requestNote} onChange={e=>setRequestNote(e.target.value)} placeholder="مثلًا: هل تم تأكيد القاعة؟"/></div>
   </Modal>
   <Modal open={modal==='deadline-decide'} title={`مراجعة تغيير الموعد — ${selected?.title||''}`} onClose={()=>setModal(null)} footer={<div className="v54-decision-actions"><button className="workspace-secondary" disabled={busy||!selected} onClick={()=>{const q=bundle.deadlineRequests.find(x=>x.milestone_id===selected?.id&&x.status==='PENDING');if(q)void act('MILESTONE_DEADLINE_DECIDE',{requestId:q.id,decision:'REJECT',note:decisionNote})}}>{busy?'جارٍ الحفظ…':'رفض الطلب'}</button><button className="workspace-primary" disabled={busy||!selected} onClick={()=>{const q=bundle.deadlineRequests.find(x=>x.milestone_id===selected?.id&&x.status==='PENDING');if(q)void act('MILESTONE_DEADLINE_DECIDE',{requestId:q.id,decision:'APPROVE',note:decisionNote})}}>{busy?'جارٍ الحفظ…':'الموافقة على الموعد'}</button></div>}>
    {selected&&(()=>{const q=bundle.deadlineRequests.find(x=>x.milestone_id===selected.id&&x.status==='PENDING');return q?<div className="v54-decision"><p><b>الموعد الأصلي:</b> {formatDateTime(q.original_due_at)}</p><p><b>الموعد المطلوب:</b> {formatDateTime(q.proposed_due_at)}</p><p><b>سبب الطلب:</b> {q.reason}</p><div className="field"><label>ملاحظة القرار (اختياري)</label><textarea className="textarea" rows={2} value={decisionNote} onChange={e=>setDecisionNote(e.target.value)}/></div><small>يُحفظ الموعد الأصلي والقرار في سجل المشروع.</small></div>:<p>لا يوجد طلب بانتظار المراجعة.</p>})()}
   </Modal>
   <Modal open={modal==='deadline'} title={`طلب تغيير موعد — ${selected?.title||''}`} onClose={()=>setModal(null)} footer={<button className="workspace-primary" disabled={busy||!deadlineDraft.proposedDueAt||!deadlineDraft.reason.trim()} onClick={()=>act('MILESTONE_DEADLINE_REQUEST',{milestoneId:selected?.id,...deadlineDraft})}>{busy?'جارٍ الإرسال…':'إرسال طلب للمشرف'}</button>}><div className="field"><label>الموعد الجديد (اليوم والساعة)</label><input className="input" type="datetime-local" value={deadlineDraft.proposedDueAt} onChange={e=>setDeadlineDraft(v=>({...v,proposedDueAt:e.target.value}))}/></div><div className="field section-gap"><label>سبب تغيير الموعد</label><textarea rows={3} className="textarea" value={deadlineDraft.reason} onChange={e=>setDeadlineDraft(v=>({...v,reason:e.target.value}))}/></div><p className="muted">لا يتغير الموعد الأصلي إلا بعد موافقة المشرف، ويبقى الطلب والقرار في السجل.</p></Modal>
   <Modal open={modal==='gs-return'} title="إعادة المشروع للسكرتير" onClose={()=>setModal(null)} footer={<button className="workspace-primary" disabled={busy||!gsReason.trim()} onClick={()=>act('PROJECT_GS_DECIDE',{initiativeId:init.id,decision:'RETURN',note:gsReason})}>إعادة للمراجعة</button>}><textarea className="textarea" rows={4} value={gsReason} onChange={e=>setGsReason(e.target.value)} placeholder="ما الذي يحتاج تعديلًا؟"/></Modal>
   <Modal open={modal==='milestone-add'||modal==='milestone-edit'} title={selected?'تعديل محطة الإنجاز':'إضافة محطة إنجاز'} onClose={()=>setModal(null)} footer={<button className="workspace-primary" disabled={busy||!milestoneForm.title.trim()||(milestoneForm.deadlineMode==='ABSOLUTE'?!milestoneForm.dueAt:!milestoneForm.relativeToMilestoneId)} onClick={()=>act(selected?'MILESTONE_DESIGN_UPDATE':'MILESTONE_DESIGN_ADD',{...(selected?{milestoneId:selected.id}:{resultId:result?.id}),...milestoneForm})}>حفظ المحطة</button>}><div className="form-grid"><div className="field full"><label>عنوان المحطة</label><input className="input" value={milestoneForm.title} onChange={e=>setMilestoneForm(v=>({...v,title:e.target.value}))}/></div><div className="field full"><label>كيف نعرف أنها تحققت؟</label><textarea className="textarea" value={milestoneForm.verificationCriteria} onChange={e=>setMilestoneForm(v=>({...v,verificationCriteria:e.target.value}))}/></div><div className="field"><label>طريقة تحديد الموعد</label><select className="select" value={milestoneForm.deadlineMode} onChange={e=>setMilestoneForm(v=>({...v,deadlineMode:e.target.value as 'ABSOLUTE'|'RELATIVE'}))}><option value="ABSOLUTE">تاريخ ووقت محددان</option>{milestones.filter(x=>x.id!==selected?.id).length>0&&<option value="RELATIVE">بعد اكتمال محطة سابقة</option>}</select></div>{milestoneForm.deadlineMode==='ABSOLUTE'?<div className="field"><label>تاريخ وتوقيت المحطة</label><input className="input" type="datetime-local" value={milestoneForm.dueAt} onChange={e=>setMilestoneForm(v=>({...v,dueAt:e.target.value}))}/></div>:<><div className="field"><label>بعد اكتمال المحطة</label><select className="select" value={milestoneForm.relativeToMilestoneId} onChange={e=>setMilestoneForm(v=>({...v,relativeToMilestoneId:e.target.value}))}><option value="">اختر المحطة المرجعية</option>{milestones.filter(x=>x.id!==selected?.id).map(x=><option key={x.id} value={x.id}>{x.title}</option>)}</select></div><div className="field"><label>بعد عدد الأيام</label><input className="input" type="number" min="0" value={milestoneForm.relativeDays} onChange={e=>setMilestoneForm(v=>({...v,relativeDays:Number(e.target.value)}))}/></div><div className="field"><label>وساعات إضافية</label><input className="input" type="number" min="0" value={milestoneForm.relativeHours} onChange={e=>setMilestoneForm(v=>({...v,relativeHours:Number(e.target.value)}))}/></div></>}</div></Modal>
 </div>;
}

// Keeps expanded content attached to its corresponding table row without an extra page.
function FragmentRow({main,detail,expanded,colSpan}:{main:React.ReactElement;detail:React.ReactElement;expanded:boolean;colSpan:number}){
 return <>{main}{expanded&&<tr className="followup-detail-row"><td colSpan={colSpan}>{detail}</td></tr>}</>;
}
